void helper_cleanup_process_queue(struct node **root) {
    if (root == NULL) {
        return;
    }
    struct node *current = *root;
    struct node *next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *root = NULL;
}

